package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="existencias_inventario") public class ExistenciaInventario { @Id @GeneratedValue private UUID id; @Column(name="empresa_id") private UUID empresaId; @ManyToOne @JoinColumn(name="sucursal_id") private Sucursal sucursal; @ManyToOne @JoinColumn(name="producto_id") private ProductoInventario producto; private BigDecimal cantidad=BigDecimal.ZERO; @Version private long version; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Sucursal getSucursal(){return sucursal;} public void setSucursal(Sucursal v){sucursal=v;} public ProductoInventario getProducto(){return producto;} public void setProducto(ProductoInventario v){producto=v;} public BigDecimal getCantidad(){return cantidad;} public void setCantidad(BigDecimal v){cantidad=v;} }
